const express = require('express');
const app = express();
app.use(express.json());

app.post('/divide', (req, res) => {
  const { a, b } = req.body || {};
  if (typeof a !== 'number' || typeof b !== 'number' || Number.isNaN(a) || Number.isNaN(b)) {
    return res.status(400).json({ error: 'a and b must both be numbers' });
  }
  res.json({ result: a / b });
});

app.listen(8022);
